@props(['feature', 'aiCategories' => []])

@php($definition = \App\Domains\Ai\Support\AiFeatureRegistry::get($feature))

<div x-data="aiLauncher(@jsExpr($feature))" x-init="init()" @ai-open.window="input = ($event.detail && $event.detail.text) || ''; open = true; attention = false; focusInput()" @keydown.escape.window="open = false">
    <button type="button" @click.stop="openPanel()" :class="attention ? 'animate-pulse' : ''" class="inline-flex min-h-16 items-center gap-2.5 rounded-full border border-brand-edge bg-card px-6 py-4 text-base font-bold text-brand-text shadow-xl shadow-ink/10 transition hover:-translate-y-0.5 hover:border-brand focus:outline-none focus:ring-2 focus:ring-brand focus:ring-offset-2" aria-label="Use Mercho for this page">
        <x-ui.icon name="spark" size="size-5" stroke="1.8" /><span>Use Mercho</span>
    </button>

    <div x-cloak x-show="open" x-transition.opacity style="display: none;" class="fixed inset-0 z-50 flex items-end justify-end bg-ink/45 sm:p-4 lg:p-6" role="dialog" aria-modal="true" aria-label="{{ $definition['label'] }}" @click="open = false">
        <section x-show="open" x-transition:enter="transition duration-200 ease-out" x-transition:enter-start="translate-y-4 opacity-0 sm:translate-y-0 sm:translate-x-4" x-transition:enter-end="translate-y-0 opacity-100 sm:translate-x-0" @click.stop class="flex max-h-[100dvh] w-full flex-col overflow-hidden rounded-t-[1.75rem] border border-rule bg-card text-ink shadow-2xl sm:max-h-[calc(100dvh-2rem)] sm:max-w-xl sm:rounded-2xl lg:max-w-2xl">
            <header class="flex shrink-0 items-start justify-between gap-4 border-b border-rule bg-card px-5 py-5 sm:px-7">
                <div class="min-w-0"><div class="flex items-center gap-2 text-brand-text"><span class="flex size-8 items-center justify-center rounded-xl bg-brand-wash" aria-hidden="true"><x-ui.icon name="spark" size="size-4" /></span><span class="text-[11px] font-bold uppercase tracking-[0.14em]">Mercho assistant</span></div><h2 class="mt-3 text-xl font-display font-extrabold tracking-tight" x-text="title"></h2><p class="mt-1 max-w-lg text-xs leading-5 text-ink-3" x-text="description"></p></div>
                <button type="button" @click="open = false" class="inline-flex min-h-11 min-w-11 shrink-0 items-center justify-center rounded-xl text-ink-3 hover:bg-tint hover:text-ink focus:outline-none focus:ring-2 focus:ring-brand" aria-label="Close Mercho panel"><svg class="size-5" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="m6 6 12 12M18 6 6 18" stroke-linecap="round" /></svg></button>
            </header>

            <div class="min-h-0 flex-1 overflow-y-auto overscroll-contain px-5 py-5 sm:px-7 sm:py-6">
                <template x-if="isListing"><div class="space-y-5"><div class="rounded-2xl border border-rule bg-surface p-4"><p class="text-sm font-bold">Add source material</p><p class="mt-1 text-xs leading-5 text-ink-3">Upload several images. Each image can become a separate draft, or group angles together.</p><label class="mt-4 block text-xs font-semibold text-ink-2"><span x-text="feature === 'products' ? 'Product photos' : 'Service or portfolio photos'"></span><input type="file" multiple accept="image/jpeg,image/png,image/webp" @change="selectPhotos($event)" class="mt-2 block min-h-12 w-full rounded-xl border border-rule-strong bg-card p-3 text-sm text-ink file:mr-3 file:rounded-lg file:border-0 file:bg-brand-wash file:px-3 file:py-1.5 file:text-xs file:font-bold file:text-brand-text"></label><p class="mt-2 text-[11px] text-ink-3"><span x-text="photos.length"></span> photo(s) selected</p><button type="button" x-show="photos.length > 1" @click="suggestGroups" :disabled="grouping" class="mt-3 min-h-10 rounded-xl border border-brand-edge px-3 text-xs font-bold text-brand-text hover:bg-brand-wash disabled:opacity-50" x-text="grouping ? 'Suggesting groups…' : 'Suggest photo groups'"></button><p x-show="groupReason" x-text="groupReason" class="mt-2 text-[11px] leading-4 text-ink-3"></p></div><div class="grid gap-4 sm:grid-cols-2"><label class="block text-xs font-semibold text-ink-2 sm:col-span-2">Optional hint<textarea x-model="input" rows="2" class="mt-2 w-full rounded-xl border border-rule-strong bg-card p-3 text-sm text-ink focus:border-brand focus:outline-none focus:ring-2 focus:ring-brand/20" :placeholder="feature === 'products' ? 'Ankara bag, 15,000' : 'Bridal makeup, 2 hours, from 35,000'"></textarea></label><label class="block text-xs font-semibold text-ink-2 sm:col-span-2"><span x-text="feature === 'products' ? 'Or paste a product list' : 'Or describe several services'"></span><textarea x-model="batchText" rows="3" class="mt-2 w-full rounded-xl border border-rule-strong bg-card p-3 text-sm text-ink focus:border-brand focus:outline-none focus:ring-2 focus:ring-brand/20" :placeholder="feature === 'products' ? 'Ankara bag 15k, leather sandals 12k, tote bag 8k' : 'Bridal makeup, gele tying, lashes, home service makeup'"></textarea></label></div><label class="inline-flex min-h-11 items-center gap-2 text-xs text-ink-2"><input type="checkbox" x-model="groupPhotos" class="size-4 rounded border-rule-strong accent-brand"> Treat all selected photos as one grouped draft</label></div></template>

                <template x-if="!isListing"><div class="space-y-4"><template x-if="feature === 'content'"><div class="grid gap-3 sm:grid-cols-2"><label class="block text-xs font-semibold text-ink-2">Action<select x-model="contentMode" class="mt-2 min-h-11 w-full rounded-xl border border-rule-strong bg-card px-3 text-sm text-ink"><option value="rewrite">Improve wording</option><option value="translate">Translate</option></select></label><label x-show="contentMode === 'translate'" class="block text-xs font-semibold text-ink-2">Language<select x-model="language" class="mt-2 min-h-11 w-full rounded-xl border border-rule-strong bg-card px-3 text-sm text-ink"><option>English</option><option>Nigerian Pidgin</option><option>Yoruba</option><option>Igbo</option><option>Hausa</option></select></label></div></template><label class="block text-xs font-semibold text-ink-2"><span x-text="feature === 'analytics' ? 'Ask about your store' : (feature === 'order-chat' ? 'Draft a reply from this thread' : 'Text for Mercho to work on')"></span><textarea x-ref="input" x-model="input" rows="6" class="mt-2 w-full rounded-2xl border border-rule-strong bg-card p-4 text-sm leading-6 text-ink focus:border-brand focus:outline-none focus:ring-2 focus:ring-brand/20" :placeholder="feature === 'analytics' ? 'Which listings attracted the most interest?' : 'Paste or type the text you want to improve…'"></textarea></label></div></template>

                <template x-if="feature === 'appearance'"><div class="mt-5 rounded-2xl border border-rule bg-surface p-4"><p class="text-sm font-bold">Use your logo as a starting point</p><p class="mt-1 text-xs leading-5 text-ink-3">We suggest a brand color and accent. Nothing changes until you confirm.</p><input type="file" accept="image/jpeg,image/png,image/webp" @change="extractLogo($event.target.files[0])" class="mt-4 block min-h-12 w-full rounded-xl border border-rule-strong bg-card p-3 text-sm text-ink file:mr-3 file:rounded-lg file:border-0 file:bg-brand-wash file:px-3 file:py-1.5 file:text-xs file:font-bold file:text-brand-text"><div x-show="logoResult" x-cloak class="mt-3 flex flex-wrap items-center justify-between gap-3 rounded-xl border border-rule bg-card p-3 text-xs"><span x-text="logoLabel()"></span><button type="button" x-show="logoDraftId" @click="confirmLogoColors" class="min-h-10 rounded-lg bg-brand px-3 text-[11px] font-bold text-brand-ink">Confirm colors</button></div></div></template>

                <div x-show="estimate" x-cloak class="mt-5 flex items-start gap-3 rounded-2xl border border-rule bg-surface p-4 text-xs text-ink-2"><svg class="mt-0.5 size-4 shrink-0 text-brand-text" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M12 11v5M12 8h.01" stroke-linecap="round" /></svg><span><span x-text="estimate ? estimate.allowed + ' of ' + estimate.requested + ' item(s) fit your current Mercho credits.' : ''"></span><span x-show="estimate && estimate.allowed < estimate.requested" class="ml-1 font-semibold text-warn-text">Upgrade to run the rest.</span></span></div>
                <div x-show="result" x-cloak class="mt-5 rounded-2xl border border-brand-edge bg-brand-wash p-4"><div class="flex items-center justify-between gap-3"><p class="text-sm font-bold text-brand-text">Progress</p><span x-show="loading" class="size-4 animate-spin rounded-full border-2 border-brand-edge border-t-brand" aria-label="Loading"></span></div><p class="mt-1 text-xs leading-5 text-ink-2" x-text="resultLabel()"></p><div x-show="jobs.length" class="mt-3 space-y-2"><template x-for="job in jobs" :key="job.id"><div class="flex items-center justify-between gap-3 rounded-xl border border-brand-edge bg-card px-3 py-2.5 text-xs"><span x-text="jobLabel(job)"></span><span class="font-semibold" :class="job.status === 'failed' ? 'text-danger-text' : (job.status === 'succeeded' ? 'text-ok-text' : 'text-ink-2')" x-text="job.status"></span><button type="button" x-show="job.status === 'failed'" @click="retryJob(job)" class="font-bold text-brand-text">Retry</button></div></template></div></div>

                <div x-show="drafts.length" x-cloak class="mt-5 space-y-3"><div class="flex items-center justify-between gap-3"><div><p class="text-sm font-bold">Review drafts</p><p class="mt-1 text-[11px] text-ink-3">Nothing is published until you confirm.</p></div><label class="inline-flex min-h-10 items-center gap-2 text-xs text-ink-2"><input type="checkbox" @change="toggleAllDrafts($event)" class="size-4 rounded border-rule-strong accent-brand"> All</label></div><template x-for="draft in drafts" :key="draft.id || draft.payload.error"><article class="rounded-2xl border border-rule bg-surface p-4"><template x-if="draft.payload.error"><p class="text-xs leading-5 text-danger-text" x-text="draft.payload.error"></p></template><template x-if="!draft.payload.error"><div class="flex gap-3"><input type="checkbox" :value="draft.id" x-model="selected" class="mt-1 size-4 rounded border-rule-strong accent-brand"><div class="min-w-0 flex-1 space-y-2"><input x-model="draft.payload.name" class="min-h-10 w-full rounded-xl border border-rule-strong bg-card px-3 text-sm font-bold text-ink"><textarea x-model="draft.payload.description" rows="3" class="w-full rounded-xl border border-rule-strong bg-card p-3 text-xs leading-5 text-ink"></textarea><div class="grid gap-2 sm:grid-cols-2"><template x-if="feature === 'products'"><div class="contents"><input x-model="draft.payload.category" list="ai-categories" class="min-h-10 rounded-xl border border-rule-strong bg-card px-3 text-xs text-ink" placeholder="Category (from your list or new)"><input x-model="draft.payload.price" type="number" min="0" step="0.01" class="min-h-10 rounded-xl border border-rule-strong bg-card px-3 text-xs text-ink" placeholder="Price"><input x-model="draft.payload.price_hint" class="min-h-10 rounded-xl border border-rule-strong bg-card px-3 text-xs text-ink" placeholder="Suggested price (reference)"><input x-model="draft.payload.tags" class="min-h-10 rounded-xl border border-rule-strong bg-card px-3 text-xs text-ink sm:col-span-2" placeholder="Tags, comma separated"><input x-model="draft.payload.variants" class="min-h-10 rounded-xl border border-rule-strong bg-card px-3 text-xs text-ink sm:col-span-2" placeholder="Variants, comma separated"><input x-model="draft.payload.seo_title" class="min-h-10 rounded-xl border border-rule-strong bg-card px-3 text-xs text-ink sm:col-span-2" placeholder="SEO title"><textarea x-model="draft.payload.seo_description" rows="2" class="rounded-xl border border-rule-strong bg-card p-3 text-xs text-ink sm:col-span-2" placeholder="SEO description"></textarea></div></template><template x-if="feature === 'services'"><div class="contents"><textarea x-model="draft.payload.packages" rows="2" class="rounded-xl border border-rule-strong bg-card p-3 text-xs text-ink" placeholder="Packages or tiers"></textarea><input x-model="draft.payload.duration" class="min-h-10 rounded-xl border border-rule-strong bg-card px-3 text-xs text-ink" placeholder="Duration"><textarea x-model="draft.payload.what_to_expect" rows="2" class="rounded-xl border border-rule-strong bg-card p-3 text-xs text-ink sm:col-span-2" placeholder="What to expect"></textarea><input x-model="draft.payload.price_hint" class="min-h-10 rounded-xl border border-rule-strong bg-card px-3 text-xs text-ink" placeholder="Suggested price"><textarea x-model="draft.payload.faq" rows="2" class="rounded-xl border border-rule-strong bg-card p-3 text-xs text-ink" placeholder="Service FAQ"></textarea><textarea x-model="draft.payload.booking_questions" rows="2" class="rounded-xl border border-rule-strong bg-card p-3 text-xs text-ink sm:col-span-2" placeholder="Booking questions"></textarea><input x-model="draft.payload.seo_title" class="min-h-10 rounded-xl border border-rule-strong bg-card px-3 py-2 text-xs text-ink sm:col-span-2" placeholder="SEO title"><textarea x-model="draft.payload.seo_description" rows="2" class="rounded-xl border border-rule-strong bg-card p-3 text-xs text-ink sm:col-span-2" placeholder="SEO description"></textarea></div></template></div><p class="text-[11px] text-ink-3">Suggested prices are recommendations. Review before confirming.</p><div class="flex flex-wrap justify-end gap-2 pt-2"><button type="button" x-show="!draft.confirmed" @click="regenerateDraft(draft)" class="min-h-10 rounded-xl border border-rule-strong px-3 text-[11px] font-bold text-ink-2">Regenerate</button><button type="button" x-show="!draft.confirmed" @click="discard(draft.id)" class="min-h-10 rounded-xl border border-rule-strong px-3 text-[11px] font-bold text-ink-2">Discard</button><button type="button" x-show="!draft.confirmed" @click="confirm(draft.id)" class="min-h-10 rounded-xl bg-brand px-3 text-[11px] font-bold text-brand-ink">Confirm</button><span x-show="draft.confirmed" class="text-xs font-semibold text-ok-text">Confirmed</span></div></div></div></template></article></template><div class="sticky bottom-0 -mx-1 flex gap-2 border-t border-rule bg-card/95 py-3 backdrop-blur"><button type="button" x-show="selected.length" @click="confirmSelected" class="min-h-12 flex-1 rounded-xl bg-brand px-4 text-xs font-bold text-brand-ink">Confirm selected</button><button type="button" x-show="hasMultipleUnconfirmed()" @click="confirmAll" class="min-h-12 flex-1 rounded-xl border border-brand-edge px-4 text-xs font-bold text-brand-text">Confirm all</button></div></div>
                <div x-show="draftId && !isListing" x-cloak class="mt-5 rounded-2xl border border-rule bg-surface p-4"><p class="text-xs font-bold">Review result</p><pre x-text="format(result)" class="mt-2 max-h-56 overflow-auto whitespace-pre-wrap text-xs leading-5 text-ink"></pre><button type="button" x-show="feature === 'content' && result && result.text" @click="confirmContent" class="mt-3 min-h-12 w-full rounded-xl bg-brand px-4 text-xs font-bold text-brand-ink">Use this text</button></div>
                <div x-show="feature === 'appearance' && result && result.presets" x-cloak class="mt-5 grid gap-3 sm:grid-cols-3"><template x-for="(preset, index) in (result && result.presets ? result.presets : [])" :key="index"><button type="button" @click="confirmPreset(index)" class="rounded-2xl border border-rule bg-surface p-3 text-left transition hover:-translate-y-0.5 hover:border-brand-edge focus:outline-none focus:ring-2 focus:ring-brand"><span class="block h-12 rounded-xl" :style="presetStyle(preset)"></span><span class="mt-3 block text-xs font-bold text-ink" x-text="preset.theme_key"></span><span class="mt-1 block text-[11px] leading-4 text-ink-3" x-text="preset.reason"></span><span class="mt-3 block text-[11px] font-bold text-brand-text">Choose preset</span></button></template></div>
            </div>
            <footer class="shrink-0 border-t border-rule bg-card px-5 py-4 pb-[calc(1rem+env(safe-area-inset-bottom))] sm:px-7"><p class="mb-3 text-[11px] leading-4 text-ink-3">You stay in control. Review every suggestion before it is added or applied.</p><button type="button" @click.stop="generate" :disabled="!canGenerate()" class="min-h-14 w-full rounded-xl bg-brand px-5 text-sm font-bold text-brand-ink transition hover:bg-brand-hover focus:outline-none focus:ring-2 focus:ring-brand focus:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50"><span x-text="loading ? 'Working…' : (isListing ? 'Create drafts' : 'Use Mercho')"></span></button></footer>
        </section>
    </div>
</div>

<datalist id="ai-categories">@foreach ($aiCategories as $cat)<option value="{{ $cat }}">@endforeach</datalist><script>
    function aiLauncher(feature) {
        return {
            feature, title: {products: 'Create product drafts', services: 'Create service drafts', appearance: 'Shape your storefront', content: 'Improve this content', analytics: 'Understand your store', 'order-chat': 'Help with this conversation'}[feature] || @js($definition['label']), description: {products: 'Turn photos or a product list into editable drafts.', services: 'Turn your offer, photos, or voice transcript into editable service drafts.', appearance: 'Generate a few considered directions for your theme and colors.', content: 'Rewrite or translate the selected content, then choose what to keep.', analytics: 'Get a plain-language summary from this store’s own numbers.', 'order-chat': 'Prepare a reply or summary. You always decide what to send.'}[feature] || 'Review every suggestion before it is applied.',
            isListing: ['products', 'services'].includes(feature), open: false, loading: false, attention: false, grouping: false, input: '', batchText: '', groupPhotos: false, photoGroups: null, groupReason: '', photos: [], jobs: [], drafts: [], selected: [], estimate: null, result: null, draftId: null, logoResult: null, logoDraftId: null, contentMode: 'rewrite', language: 'English',
            init() { try { this.attention = !localStorage.getItem(`mypage-ai-seen-${feature}`); localStorage.setItem(`mypage-ai-seen-${feature}`, '1'); } catch { this.attention = false; } }, openPanel() { this.open = true; this.attention = false; this.focusInput(); }, focusInput() { this.$nextTick(() => { if (this.$refs.input) this.$refs.input.focus(); }); }, async read(response) { try { return await response.json(); } catch { return {message: 'The Mercho request could not be read.'}; } },
            async generate() { this.loading = true; try { const requestedCredits = this.feature === 'appearance' ? 3 : 1; const creditResponse = await fetch(@js(route('dashboard.ai.estimate')), {method: 'POST', headers: {'Content-Type': 'application/json', 'Accept': 'application/json', 'X-CSRF-TOKEN': @js(csrf_token())}, body: JSON.stringify({feature: this.feature, item_count: requestedCredits})}); this.estimate = await this.read(creditResponse); if (!creditResponse.ok || this.estimate.allowed < requestedCredits) { this.result = {error: 'Your current Mercho limit does not cover this run. Upgrade to continue.'}; return; } if (this.feature === 'analytics') { const endpoint = this.input.trim() ? @js(route('dashboard.analytics.ask')) : @js(route('dashboard.analytics.digest')); const options = this.input.trim() ? {method: 'POST', headers: {'Content-Type': 'application/json', 'Accept': 'application/json', 'X-CSRF-TOKEN': @js(csrf_token())}, body: JSON.stringify({question: this.input})} : {method: 'POST', headers: {'Accept': 'application/json', 'X-CSRF-TOKEN': @js(csrf_token())}}; const response = await fetch(endpoint, options); const data = await this.read(response); this.result = response.ok ? data.result : {error: data.message || 'The analytics request could not be completed.'}; return; } if (this.feature === 'order-chat') { const threadId = window.location.pathname.split('/').filter(Boolean).pop(); const response = await fetch(`/chat/${threadId}/ai-suggestion`, {method: 'POST', headers: {'Accept': 'application/json', 'X-CSRF-TOKEN': @js(csrf_token())}}); const data = await this.read(response); this.result = response.ok ? data.suggestion : {error: data.message || 'Enable chat Mercho to get a suggestion.'}; return; } if (!this.isListing) { const response = await fetch(@js(route('dashboard.ai.contextual')), {method: 'POST', headers: {'Content-Type': 'application/json', 'Accept': 'application/json', 'X-CSRF-TOKEN': @js(csrf_token())}, body: JSON.stringify({feature: this.feature, input: {text: this.input, mode: this.contentMode, language: this.language}})}); const data = await this.read(response); this.result = response.ok ? data.result : {error: data.message || 'Mercho could not prepare a draft.'}; this.draftId = data.draft_id; return; } const textItems = this.batchText.split(/[,\n]/).map(item => item.trim()).filter(Boolean).map(text => ({text})); const requested = textItems.length + (this.photos.length ? (this.photoGroups?.length || (this.groupPhotos ? 1 : this.photos.length)) : 0); const estimateResponse = await fetch(@js(route('dashboard.ai.estimate')), {method: 'POST', headers: {'Content-Type': 'application/json', 'Accept': 'application/json', 'X-CSRF-TOKEN': @js(csrf_token())}, body: JSON.stringify({feature: this.feature, item_count: requested})}); this.estimate = await this.read(estimateResponse); const operations = []; if (textItems.length) { const response = await fetch(@js(route('dashboard.ai.batch')), {method: 'POST', headers: {'Content-Type': 'application/json', 'Accept': 'application/json', 'X-CSRF-TOKEN': @js(csrf_token())}, body: JSON.stringify({feature: this.feature, items: textItems})}); const data = await this.read(response); if (response.ok) operations.push(...data.operations); } if (this.photos.length) { const form = new FormData(); form.append('feature', this.feature); form.append('hint', this.input); form.append('group', this.groupPhotos ? '1' : '0'); if (this.photoGroups?.length) form.append('groups', JSON.stringify(this.photoGroups)); this.photos.forEach(photo => form.append('photos[]', photo)); const response = await fetch(@js(route('dashboard.ai.photo-listing')), {method: 'POST', headers: {'Accept': 'application/json', 'X-CSRF-TOKEN': @js(csrf_token())}, body: form}); const data = await this.read(response); if (response.ok) operations.push(...data.operations); } this.jobs = operations.map(operation => ({...operation, status: 'queued'})); this.result = {status: 'queued', count: operations.length}; operations.forEach(operation => this.poll(operation.id)); } catch (error) { this.result = {error: error.message || 'The Mercho request could not be completed.'}; } finally { this.loading = false; } },
            async poll(id) { for (let attempt = 0; attempt < 30; attempt++) { await new Promise(resolve => setTimeout(resolve, 1500)); const response = await fetch(`/ai/operations/${id}`, {headers: {'Accept': 'application/json'}}); if (!response.ok) return; const data = await this.read(response); this.jobs = this.jobs.map(job => job.id === id ? {...job, status: data.operation.status} : job); if (data.operation.status === 'succeeded') { this.drafts.push({id: data.draft_id, payload: data.operation.output}); return; } if (data.operation.status === 'failed') { this.drafts.push({id: null, payload: {error: data.operation.error || 'This item could not be processed.'}}); return; } } }, async retryJob(job) { const response = await fetch(`/ai/operations/${job.id}/retry`, {method: 'POST', headers: {'Accept': 'application/json', 'X-CSRF-TOKEN': @js(csrf_token())}}); if (response.ok) { this.jobs = this.jobs.map(item => item.id === job.id ? {...item, status: 'queued'} : item); this.poll(job.id); } },
            async save(draft) { const payload = {...draft.payload}; for (const key of ['tags', 'variants', 'packages', 'faq', 'booking_questions']) { if (typeof payload[key] === 'string') payload[key] = payload[key].split(',').map(item => item.trim()).filter(Boolean); } await fetch(`/ai/drafts/${draft.id}`, {method: 'PATCH', headers: {'Content-Type': 'application/json', 'Accept': 'application/json', 'X-CSRF-TOKEN': @js(csrf_token())}, body: JSON.stringify(payload)}); }, async confirm(id) { await this.save(this.drafts.find(draft => draft.id === id)); const response = await fetch(`/ai/drafts/${id}/approve`, {method: 'POST', headers: {'Accept': 'application/json', 'X-CSRF-TOKEN': @js(csrf_token())}}); if (response.ok) this.drafts = this.drafts.map(draft => draft.id === id ? {...draft, confirmed: true} : draft); }, async confirmSelected() { const ids = this.selected.filter(id => this.drafts.some(draft => draft.id === id && !draft.confirmed)); for (const id of ids) await this.save(this.drafts.find(draft => draft.id === id)); const response = await fetch(@js(route('dashboard.ai.drafts.confirm-selected')), {method: 'POST', headers: {'Content-Type': 'application/json', 'Accept': 'application/json', 'X-CSRF-TOKEN': @js(csrf_token())}, body: JSON.stringify({draft_ids: ids})}); if (response.ok) this.drafts = this.drafts.map(draft => ids.includes(draft.id) ? {...draft, confirmed: true} : draft); }, async confirmAll() { for (const draft of this.drafts.filter(draft => draft.id && !draft.confirmed)) await this.confirm(draft.id); }, async discard(id) { const response = await fetch(`/ai/drafts/${id}/discard`, {method: 'POST', headers: {'Accept': 'application/json', 'X-CSRF-TOKEN': @js(csrf_token())}}); if (response.ok) this.drafts = this.drafts.filter(draft => draft.id !== id); }, async regenerate(id) { const response = await fetch(`/ai/drafts/${id}/regenerate`, {method: 'POST', headers: {'Accept': 'application/json', 'X-CSRF-TOKEN': @js(csrf_token())}}); if (response.ok) { const data = await this.read(response); this.drafts.push({id: data.draft.id, payload: data.draft.payload}); } },
            async confirmPreset(index) { const response = await fetch(`/ai/drafts/${this.draftId}/approve`, {method: 'POST', headers: {'Content-Type': 'application/json', 'Accept': 'application/json', 'X-CSRF-TOKEN': @js(csrf_token())}, body: JSON.stringify({preset: index})}); if (response.ok) this.result = {...this.result, confirmed: true}; }, async suggestGroups() { if (this.photos.length < 2 || this.grouping) return; this.grouping = true; const form = new FormData(); form.append('feature', this.feature); this.photos.forEach(photo => form.append('photos[]', photo)); const response = await fetch(@js(route('dashboard.ai.photo-groups')), {method: 'POST', headers: {'Accept': 'application/json', 'X-CSRF-TOKEN': @js(csrf_token())}, body: form}); const data = await this.read(response); if (response.ok) { this.photoGroups = data.groups; this.groupReason = data.reason || 'Review the suggested groups before creating drafts.'; } else this.groupReason = data.message || 'Photo grouping could not be suggested.'; this.grouping = false; }, async confirmContent() { if (!this.draftId || !this.result?.text) return; const response = await fetch(`/ai/drafts/${this.draftId}/approve`, {method: 'POST', headers: {'Accept': 'application/json', 'X-CSRF-TOKEN': @js(csrf_token())}}); if (response.ok) { this.$dispatch('ai-result', {feature: 'content', text: this.result.text}); this.result = {...this.result, confirmed: true}; } }, async extractLogo(file) { if (!file) return; const form = new FormData(); form.append('logo', file); const response = await fetch(@js(route('dashboard.ai.logo-colors')), {method: 'POST', headers: {'Accept': 'application/json', 'X-CSRF-TOKEN': @js(csrf_token())}, body: form}); const data = await this.read(response); this.logoResult = data; this.logoDraftId = data.draft_id || null; },             async confirmLogoColors() { const response = await fetch(`/ai/drafts/${this.logoDraftId}/approve`, {method: 'POST', headers: {'Accept': 'application/json', 'X-CSRF-TOKEN': @js(csrf_token())}}); if (response.ok) this.logoDraftId = null; },
            selectPhotos(event) { this.photos = Array.from(event.target.files ?? []); this.photoGroups = null; this.groupReason = ''; },
            toggleAllDrafts(event) { this.selected = event.target.checked ? this.drafts.filter(draft => draft.id).map(draft => draft.id) : []; },
            regenerateDraft(draft) { this.save(draft).then(() => this.regenerate(draft.id)); },
            format(value) { return typeof value === 'string' ? value : JSON.stringify(value, null, 2); },
            jobLabel(job) { return `Item ${job.index + 1}`; },
            presetStyle(preset) { return `background:${preset.brand_color}`; },
            hasMultipleUnconfirmed() { return this.drafts.filter(draft => draft.id && !draft.confirmed).length > 1; },
            canGenerate() { if (this.loading) return false; if (this.isListing) return !!(this.photos.length || this.batchText.trim()); if (['analytics', 'order-chat'].includes(this.feature)) return true; return !!this.input.trim(); },
            resultLabel() { if (!this.result) return ''; if (this.result.status === 'queued') return `${this.result.count} draft(s) queued. They will appear below as they finish.`; return this.result.error || ''; },
            logoLabel() { return this.logoResult ? `Brand ${this.logoResult.brand_color} · accent ${this.logoResult.accent_color}` : ''; },
        };
    }

    document.addEventListener('alpine:init', () => Alpine.data('aiLauncher', aiLauncher));
</script>
